134	// that has something to say (nothing when every registry answered: only the count).
135	// Order: Pending or Interrupted, Failed (red), Refused, Partial (orange), No result,
136	// Skipped (grey). Each name list is abbreviated by fitNames to the room the header
137	// gives a value, so a +N is never lost; Skipped drops its hint first. termWidth 0
138	// or less means the width is not known yet. At most shortcut.HeaderRows lines.
139	func searchHeaderInfo(images int, s searchSummary, termWidth int) []shortcut.HeaderInfo {
140		type line struct {
141			key    string
142			names  []string
143			count  string // a ready value, instead of names
144			suffix string
145			style  lipgloss.Style
146		}
