1	package ociresources
2	
3	import (
4		"fmt"
5		"math"
6		"strings"
7	
8		"charm.land/lipgloss/v2"
9		"github.com/charmbracelet/x/ansi"
10	
11		"github.com/anthnel/devdesk/internal/imagesearch"
12		"github.com/anthnel/devdesk/internal/ui/shortcut"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	// noWidthLimit tells fitNames the header width is not known yet (before the first
17	// WindowSizeMsg): nothing is abbreviated.
18	const noWidthLimit = math.MaxInt
19	
20	// skippedHint explains a Skipped line; it is the first thing fitNames drops.
21	var skippedHint = fmt.Sprintf(" (type %d+ characters)", imagesearch.CatalogMinQueryRunes)
22	
23	// fitNames joins names with ", " and appends suffix, within width cells
24	// (ansi.StringWidth). It tries, in order, and returns the first that fits:
25	//  1. every name + suffix;
26	//  2. the first k names + ", +N" + suffix, k from len-1 down to 1;
27	//  3. "+N" + suffix (N = len(names));
28	//  4. steps 1 to 3 again without the suffix (only when suffix != "").
29	//
30	// When nothing fits it returns "+N" (wider than width: the header clips it).
31	// Empty names return "".
32	func fitNames(names []string, suffix string, width int) string {
33		if len(names) == 0 {
34			return ""
35		}
36		fits := func(s string) bool { return ansi.StringWidth(s) <= width }
37		try := func(suffix string) (string, bool) {
38			if all := strings.Join(names, ", ") + suffix; fits(all) {
39				return all, true
40			}
41			for k := len(names) - 1; k >= 1; k-- {
42				s := fmt.Sprintf("%s, +%d%s", strings.Join(names[:k], ", "), len(names)-k, suffix)
43				if fits(s) {
44					return s, true
45				}
46			}
47			if s := fmt.Sprintf("+%d%s", len(names), suffix); fits(s) {
48				return s, true
49			}
50			return "", false
51		}
52		if s, ok := try(suffix); ok {
53			return s
54		}
55		if suffix != "" {
56			if s, ok := try(""); ok {
57				return s
58			}
59		}
60		return fmt.Sprintf("+%d", len(names))
61	}
62	
63	// searchSummary is what the level 1 header says about the lot, names in form order.
64	type searchSummary struct {
65		Pending     int      // in the live lot, no answer yet
66		Interrupted []string // the lot was abandoned (→) before they answered
67		Failed      []string
68		Refused     []string
69		Partial     []string // ok or no result, cut at a cap
70		NoResult    []string // answered, nothing matches (Skipped excluded)
71		Skipped     []string // catalog not walked: query too short
72	}
73	
74	// summarizeSearch sorts the lot's keys into classes. Pure; names are label(key),
75	// in the order of keys.
76	func summarizeSearch(keys []string, outcomes map[string]imagesearch.Outcome, live bool,
77		label func(key string) string) searchSummary {
78		var s searchSummary
79		for _, k := range keys {
80			oc, ok := outcomes[k]
81			if !ok {
82				if live {
83					s.Pending++
84				} else {
85					s.Interrupted = append(s.Interrupted, label(k))
86				}
87				continue
88			}
89			switch oc.Verdict {
90			case imagesearch.VerdictFailed:
91				s.Failed = append(s.Failed, label(k))
92			case imagesearch.VerdictRefused:
93				s.Refused = append(s.Refused, label(k))
94			case imagesearch.VerdictNoResult:
95				if oc.Skipped {
96					s.Skipped = append(s.Skipped, label(k))
97					continue
98				}
99				s.NoResult = append(s.NoResult, label(k))
100				if oc.Partial {
101					s.Partial = append(s.Partial, label(k))
102				}
103			case imagesearch.VerdictOK:
104				if oc.Partial {
105					s.Partial = append(s.Partial, label(k))
106				}
107			}
108		}
109		return s
110	}
111	
112	// searchSummary summarizes the current level 1 lot (live: b.gen == b.searchGen).
113	func (b *RegistryBrowser) searchSummary() searchSummary {
114		return summarizeSearch(b.searchKeys, b.outcomes, b.gen == b.searchGen, b.entryLabel)
115	}
116	
117	// entryLabel is the Registry column's label for key: entryAlias, else the URL,
118	// else the key itself.
119	func (b *RegistryBrowser) entryLabel(key string) string {
120		e := b.entryFor(key)
121		if e == nil {
122			return key
123		}
124		if a := entryAlias(*e); a != "" {
125			return a
126		}
127		if e.URL != "" {
128			return e.URL
129		}
130		return key
131	}
132	
133	// searchHeaderInfo is the level 1 header: the image count, then one line per class
134	// that has something to say (nothing when every registry answered: only the count).
135	// Order: Pending or Interrupted, Failed (red), Refused, Partial (orange), No result,
136	// Skipped (grey). Each name list is abbreviated by fitNames to the room the header
137	// gives a value, so a +N is never lost; Skipped drops its hint first. termWidth 0
138	// or less means the width is not known yet. At most shortcut.HeaderRows lines.
139	func searchHeaderInfo(images int, s searchSummary, termWidth int) []shortcut.HeaderInfo {
140		type line struct {
141			key    string
142			names  []string
143			count  string // a ready value, instead of names
144			suffix string
145			style  lipgloss.Style
146		}
147		warn := theme.HeaderWarnValueStyle()
148		var lines []line
149		if s.Pending > 0 {
150			lines = append(lines, line{key: "Pending", count: fmt.Sprintf("%d", s.Pending), style: theme.HeaderValueStyle})
151		}
152		lines = append(lines,
153			line{key: "Interrupted", names: s.Interrupted, style: warn},
154			line{key: "Failed", names: s.Failed, style: theme.SeverityTextStyle("CRITICAL")},
155			line{key: "Refused", names: s.Refused, style: warn},
156			line{key: "Partial", names: s.Partial, style: warn},
157			line{key: "No result", names: s.NoResult, style: theme.DimStyle},
158			line{key: "Skipped", names: s.Skipped, suffix: skippedHint, style: theme.DimStyle},
159		)
160		var kept []line
161		keys := []string{"Images"}
162		for _, l := range lines {
163			if l.count == "" && len(l.names) == 0 {
164				continue
165			}
166			// Unreachable today: Pending and Interrupted exclude each other, so at most
167			// six classes plus Images fit the budget. A new line (IS-14) must revisit
168			// this bound rather than be cut silently here.
169			if len(kept)+1 >= shortcut.HeaderRows {
170				break
171			}
172			kept = append(kept, l)
173			keys = append(keys, l.key)
174		}
175		room := noWidthLimit
176		if termWidth > 0 {
177			room = shortcut.HeaderValueWidth(termWidth, keys)
178		}
179		infos := []shortcut.HeaderInfo{{Key: "Images", Value: fmt.Sprintf("%d", images), Style: theme.HeaderValueStyle}}
180		for _, l := range kept {
181			v := l.count
182			if v == "" {
183				v = fitNames(l.names, l.suffix, room)
184			}
185			infos = append(infos, shortcut.HeaderInfo{Key: l.key, Value: v, Style: l.style})
186		}
187		return infos
188	}
