16	// DEVDESK-305 (IS-13), step 4: the level 1 header keeps each registry's verdict
17	// visible (criteria C1 to C7), read through GetHeaderInfo on a real browser.
18	
19	// headerLines returns the header's keys in order and its values by key.
20	func headerLines(m Model) ([]string, map[string]string) {
21		var keys []string
22		vals := map[string]string{}
23		for _, info := range m.GetHeaderInfo("") {
24			keys = append(keys, info.Key)
25			vals[info.Key] = info.Value
26		}
27		return keys, vals
28	}
29	
30	// fourRegistryModel opens the browser on hub, dhi.io, nexus-prod and dev, in that
31	// form order, at a terminal width wide.
32	func fourRegistryModel(t *testing.T, width int) Model {
33		t.Helper()
34		m := registryModel(t,
35			anonymousRegistry("docker.io", "hub"),
36			anonymousRegistry("dhi.io", "dhi.io"),
37			anonymousRegistry("nexus.example.com", "nexus-prod"),
38			anonymousRegistry("dev.example.com", "dev"),
39		)
40		return feed(t, m, testutil.Resize(width, 40))
41	}
42	
43	func wantHeaderKeys(t *testing.T, m Model, want ...string) map[string]string {
44		t.Helper()
45		keys, vals := headerLines(m)
46		if !slices.Equal(keys, want) {
47			t.Fatalf("header keys = %v, want %v (values %v)", keys, want, vals)
48		}
49		return vals
50	}
51	
52	// C1: a finished search names, per class, the registries that failed or refused.
53	func TestAFinishedSearchListsEachProblemByClass(t *testing.T) {
54		withImageSearcher(t, &fakeSearcher{})
55		m := searchLot(t, fourRegistryModel(t, 200))
56		m = answerFor(t, m, "hub", oneImage("nginx"), false, nil)
57		m = answerFor(t, m, "dhi.io", nil, false, imagesearch.ErrUnsupported)
58		m = answerFor(t, m, "nexus-prod", nil, false, imagesearch.ErrUnsupported)
59		m = answerFor(t, m, "dev", nil, false, errors.New("boom"))
60	
61		vals := wantHeaderKeys(t, m, "Images", "Failed", "Refused")
62		if vals["Images"] != "1" {
63			t.Errorf("Images = %q, want 1", vals["Images"])
64		}
65		if vals["Failed"] != "dev" {
66			t.Errorf("Failed = %q, want dev", vals["Failed"])
67		}
68		if vals["Refused"] != "dhi.io, nexus-prod" {
69			t.Errorf("Refused = %q, want %q (form order)", vals["Refused"], "dhi.io, nexus-prod")
70		}
71	
72		// A filter changes the image count, never the summary.
73		m = feed(t, m, testutil.Key("/"))
74		m = feed(t, m, testutil.Type("zzz")...)
75		m = feed(t, m, testutil.Key("enter"))
76		vals = wantHeaderKeys(t, m, "Images", "Failed", "Refused")
77		if vals["Images"] != "0" || vals["Failed"] != "dev" || vals["Refused"] != "dhi.io, nexus-prod" {
78			t.Errorf("header after a filter = %v, want Images 0 and the same summary", vals)
79		}
80	}
81	
82	// C2: while answers are missing, the header counts them.
83	func TestASearchInFlightCountsThePendingRegistries(t *testing.T) {
84		withImageSearcher(t, &fakeSearcher{})
85		m := searchLot(t, fourRegistryModel(t, 200))
