99	// C3: a registry cut at a cap is named, whether it answered or found nothing.
100	func TestAPartialRegistryIsNamed(t *testing.T) {
101		tests := []struct {
102			name   string
103			images []imagesearch.Image
104			want   []string
105			vals   map[string]string
106		}{
107			{"ok and partial", oneImage("nginx"), []string{"Images", "Partial"}, map[string]string{"Partial": "hub"}},
108			{"no result and partial", nil, []string{"Images", "Partial", "No result"}, // V4: Partial before No result
109				map[string]string{"Partial": "hub", "No result": "hub"}},
110		}
111		for _, tt := range tests {
112			t.Run(tt.name, func(t *testing.T) {
113				withImageSearcher(t, &fakeSearcher{})
114				m := registryModel(t, anonymousRegistry("docker.io", "hub"))
115				m = feed(t, m, testutil.Resize(200, 40))
116				m = answerFor(t, searchLot(t, m), "hub", tt.images, true, nil)
117				keys, vals := headerLines(m)
118				if !slices.Equal(keys, tt.want) {
119					t.Fatalf("header keys = %v, want %v", keys, tt.want)
120				}
121				for k, v := range tt.vals {
122					if vals[k] != v {
123						t.Errorf("%s = %q, want %q", k, vals[k], v)
124					}
125				}
126			})
127		}
128	}
129	
130	// C4: on a narrow header a list ends with +N, never silently cut.
131	func TestANarrowHeaderAbbreviatesWithACount(t *testing.T) {
132		withImageSearcher(t, &fakeSearcher{})
133		m := searchLot(t, fourRegistryModel(t, 80))
134		m = answerFor(t, m, "hub", oneImage("nginx"), false, nil)
135		m = answerFor(t, m, "dhi.io", nil, false, imagesearch.ErrUnsupported)
136		m = answerFor(t, m, "nexus-prod", nil, false, imagesearch.ErrUnsupported)
