138		vals := wantHeaderKeys(t, m, "Images", "Refused")
139		if vals["Refused"] != "dhi.io, +1" {
140			t.Errorf("Refused at 80 columns = %q, want %q", vals["Refused"], "dhi.io, +1")
141		}
142	}
143	
144	// Every class at once, long names: never more than HeaderRows lines, never a
145	// value wider than the room the header gives it.
146	func TestTheSummaryNeverOverflowsTheHeader(t *testing.T) {
147		withImageSearcher(t, &fakeSearcher{})
148		names := []string{"registry-one", "registry-two", "registry-three", "registry-four",
149			"registry-five", "registry-six", "registry-seven"}
150		for w := 50; w <= 220; w += 10 {
151			t.Run(fmt.Sprintf("width %d", w), func(t *testing.T) {
152				// The browser is a pointer: each width builds its own model.
153				m0 := registryModel(t,
154					anonymousRegistry("one.example.com", names[0]),
155					anonymousRegistry("two.example.com", names[1]),
156					anonymousRegistry("three.example.com", names[2]),
157					anonymousRegistry("four.example.com", names[3]),
158					anonymousRegistry("five.example.com", names[4]),
159					anonymousRegistry("six.example.com", names[5]),
160					anonymousRegistry("seven.example.com", names[6]),
161				)
162				m := searchLot(t, feed(t, m0, testutil.Resize(w, 40)))
163				m = answerFor(t, m, names[0], oneImage("nginx"), false, nil)
164				m = answerFor(t, m, names[1], nil, false, errors.New("boom"))
165				m = answerFor(t, m, names[2], nil, false, imagesearch.ErrUnsupported)
166				m = answerFor(t, m, names[3], oneImage("nginx"), true, nil)
167				m = answerFor(t, m, names[4], nil, false, nil)
168				m.registryBrowser.outcomes[names[5]] = imagesearch.Outcome{Verdict: imagesearch.VerdictNoResult, Skipped: true}
169				// names[6] stays pending.
170	
171				keys, vals := headerLines(m)
172				wantKeys := []string{"Images", "Pending", "Failed", "Refused", "Partial", "No result", "Skipped"}
173				if !slices.Equal(keys, wantKeys) {
174					t.Fatalf("keys = %v, want %v", keys, wantKeys)
175				}
176				if len(keys) > shortcut.HeaderRows {
177					t.Errorf("%d lines, want at most %d", len(keys), shortcut.HeaderRows)
178				}
179				room := shortcut.HeaderValueWidth(w, keys)
180				if room < 2 {
181					return
182				}
183				for _, k := range keys {
184					if got := ansi.StringWidth(vals[k]); got > room {
185						t.Errorf("%s = %q is %d cells, room is %d", k, vals[k], got, room)
186					}
187				}
188			})
189		}
190	}
191	
192	// C5: nothing to report, only the count.
193	func TestAllOKShowsOnlyTheImageCount(t *testing.T) {
194		withImageSearcher(t, &fakeSearcher{})
195		m := searchLot(t, fourRegistryModel(t, 200))
196		for _, k := range []string{"hub", "dhi.io", "nexus-prod", "dev"} {
197			m = answerFor(t, m, k, oneImage("nginx"), false, nil)
198		}
199		wantHeaderKeys(t, m, "Images")
200	}
201	
202	// C6: level 2 keeps its usual tag count; back at level 1 the summary returns.
203	func TestLevelTwoShowsTagsAndTheSummaryComesBack(t *testing.T) {
204		withImageSearcher(t, &fakeSearcher{})
205		withTagRecorder(t)
206		m := registryModel(t,
207			anonymousRegistry("docker.io", "hub"),
208			anonymousRegistry("prod.example.com", "prod"),
