15	
16	// DEVDESK-305 (IS-13), steps 2 and 3: fitNames abbreviates a list of registry
17	// names to a width; the level 1 summary is derived from the lot's keys and the
18	// verdicts.
19	
20	// ── fitNames ─────────────────────────────────────────────────────────────────
21	
22	func TestFitNames(t *testing.T) {
23		tests := []struct {
24			name   string
25			names  []string
26			suffix string
27			width  int
28			want   string
29		}{
30			{"everything fits", []string{"dhi.io", "nexus-prod"}, "", 18, "dhi.io, nexus-prod"},
31			{"one name and a count", []string{"dhi.io", "nexus-prod"}, "", 10, "dhi.io, +1"},
32			{"only a count", []string{"dhi.io", "nexus-prod"}, "", 9, "+2"},
33			{"keeps as many names as fit", []string{"a", "b", "cccccc"}, "", 8, "a, b, +1"},
34			{"one fewer name", []string{"a", "b", "cccccc"}, "", 7, "a, +2"},
35			{"suffix fits", []string{"nexus-prod"}, skippedHint, 40, "nexus-prod (type 2+ characters)"},
36			{"suffix dropped before the name (V3)", []string{"nexus-prod"}, skippedHint, 20, "nexus-prod"},
37			{"count and suffix", []string{"p1", "p2"}, skippedHint, 25, "+2 (type 2+ characters)"},
38			{"count alone when nothing else fits", []string{"nexus-prod"}, skippedHint, 5, "+1"},
39			{"width 1 overflows with the count", []string{"a", "b"}, "", 1, "+2"},
40			{"width 0 overflows with the count", []string{"a", "b", "c"}, "", 0, "+3"},
41			{"no width limit shows all", []string{"a", "b", "c"}, "", noWidthLimit, "a, b, c"},
42			{"no width limit keeps the suffix", []string{"a"}, skippedHint, noWidthLimit, "a (type 2+ characters)"},
43			{"nil names", nil, "", 40, ""},
44			{"nil names with a suffix", nil, skippedHint, 40, ""},
45			{"wide characters count for 2 cells", []string{"日本"}, "", 4, "日本"},
46			{"wide characters do not fit in 3", []string{"日本"}, "", 3, "+1"},
47		}
48		for _, tt := range tests {
49			t.Run(tt.name, func(t *testing.T) {
50				if got := fitNames(tt.names, tt.suffix, tt.width); got != tt.want {
51					t.Errorf("fitNames(%v, %q, %d) = %q, want %q", tt.names, tt.suffix, tt.width, got, tt.want)
52				}
53			})
54		}
55	}
56	
57	func TestSkippedHintReadsTheCatalogMinimum(t *testing.T) {
58		want := " (type " + strconv.Itoa(imagesearch.CatalogMinQueryRunes) + "+ characters)"
59		if skippedHint != want {
60			t.Errorf("skippedHint = %q, want %q", skippedHint, want)
61		}
62	}
63	
64	// Property: an abbreviation always says how many names it hides, and it fits
65	// whenever a bare "+N" does.
66	func TestFitNamesNeverHidesACount(t *testing.T) {
67		pool := []string{"hub", "prod", "dhi.io", "nexus-prod", "third", "日本語"}
68		for _, suffix := range []string{"", skippedHint} {
69			for n := 1; n <= len(pool); n++ {
70				names := pool[:n]
71				for width := 2; width <= 60; width++ {
72					out := fitNames(names, suffix, width)
73					if ansi.StringWidth(out) > width {
74						t.Errorf("fitNames(%v, %q, %d) = %q is %d cells wide", names, suffix, width, out, ansi.StringWidth(out))
75					}
76					list := strings.TrimSuffix(out, suffix)
77					parts := strings.Split(list, ", ")
78					shown, hidden := len(parts), 0
79					if last := parts[len(parts)-1]; strings.HasPrefix(last, "+") {
80						c, err := strconv.Atoi(strings.TrimPrefix(last, "+"))
81						if err != nil {
82							t.Errorf("fitNames(%v, %q, %d) = %q: bad count %q", names, suffix, width, out, last)
83							continue
84						}
85						shown, hidden = len(parts)-1, c
86					}
87					if shown+hidden != n {
88						t.Errorf("fitNames(%v, %q, %d) = %q shows %d and hides %d, want %d in all",
89							names, suffix, width, out, shown, hidden, n)
90					}
91				}
92			}
93		}
94	}
95	
96	// ── summarizeSearch ──────────────────────────────────────────────────────────
97	
98	func TestSummarizeSearch(t *testing.T) {
99		ok := imagesearch.Outcome{Verdict: imagesearch.VerdictOK}
100		okPartial := imagesearch.Outcome{Verdict: imagesearch.VerdictOK, Partial: true}
101		none := imagesearch.Outcome{Verdict: imagesearch.VerdictNoResult}
102		nonePartial := imagesearch.Outcome{Verdict: imagesearch.VerdictNoResult, Partial: true}
103		skipped := imagesearch.Outcome{Verdict: imagesearch.VerdictNoResult, Skipped: true}
104		refused := imagesearch.Outcome{Verdict: imagesearch.VerdictRefused}
105		failed := imagesearch.Outcome{Verdict: imagesearch.VerdictFailed}
106	
107		tests := []struct {
108			name     string
109			keys     []string
110			outcomes map[string]imagesearch.Outcome
111			live     bool
112			want     searchSummary
113		}{
114			{"no keys", nil, nil, true, searchSummary{}},
115			{"ok without a mark appears nowhere", []string{"a"}, map[string]imagesearch.Outcome{"a": ok}, true, searchSummary{}},
116			{"no outcome in a live lot is pending", []string{"a", "b"}, nil, true, searchSummary{Pending: 2}},
117			{"no outcome in an abandoned lot is interrupted", []string{"a", "b"},
118				map[string]imagesearch.Outcome{"a": ok}, false, searchSummary{Interrupted: []string{"b"}}},
119			{"failed", []string{"a"}, map[string]imagesearch.Outcome{"a": failed}, true, searchSummary{Failed: []string{"a"}}},
120			{"refused", []string{"a"}, map[string]imagesearch.Outcome{"a": refused}, true, searchSummary{Refused: []string{"a"}}},
121			{"ok partial", []string{"a"}, map[string]imagesearch.Outcome{"a": okPartial}, true, searchSummary{Partial: []string{"a"}}},
122			{"no result", []string{"a"}, map[string]imagesearch.Outcome{"a": none}, true, searchSummary{NoResult: []string{"a"}}},
123			{"no result and partial is both", []string{"a"}, map[string]imagesearch.Outcome{"a": nonePartial}, true,
124				searchSummary{NoResult: []string{"a"}, Partial: []string{"a"}}},
125			{"skipped is only skipped", []string{"a"}, map[string]imagesearch.Outcome{"a": skipped}, true,
126				searchSummary{Skipped: []string{"a"}}},
127			{"names follow the keys, not the map", []string{"z", "m", "a"},
128				map[string]imagesearch.Outcome{"a": refused, "m": refused, "z": refused}, true,
129				searchSummary{Refused: []string{"z", "m", "a"}}},
130			{"a mix", []string{"hub", "prod", "dev", "slow", "third"},
131				map[string]imagesearch.Outcome{"hub": ok, "prod": refused, "dev": failed, "slow": okPartial}, true,
132				searchSummary{Pending: 1, Failed: []string{"dev"}, Refused: []string{"prod"}, Partial: []string{"slow"}}},
133		}
134		label := func(k string) string { return "L:" + k }
135		for _, tt := range tests {
136			t.Run(tt.name, func(t *testing.T) {
137				got := summarizeSearch(tt.keys, tt.outcomes, tt.live, label)
138				// Names carry the label, not the key.
139				want := tt.want
140				for _, p := range []*[]string{&want.Interrupted, &want.Failed, &want.Refused, &want.Partial, &want.NoResult, &want.Skipped} {
141					for i, k := range *p {
142						(*p)[i] = "L:" + k
143					}
144				}
145				if !reflect.DeepEqual(got, want) {
146					t.Errorf("summarizeSearch = %+v, want %+v", got, want)
147				}
148			})
149		}
150	}
151	
152	// ── the summary as the model derives it ──────────────────────────────────────
