82	// C2: while answers are missing, the header counts them.
83	func TestASearchInFlightCountsThePendingRegistries(t *testing.T) {
84		withImageSearcher(t, &fakeSearcher{})
85		m := searchLot(t, fourRegistryModel(t, 200))
86		if got := wantHeaderKeys(t, m, "Images", "Pending")["Pending"]; got != "4" {
87			t.Errorf("Pending after submit = %q, want 4", got)
88		}
89		m = answerFor(t, m, "hub", oneImage("nginx"), false, nil)
90		if got := wantHeaderKeys(t, m, "Images", "Pending")["Pending"]; got != "3" {
91			t.Errorf("Pending after one answer = %q, want 3", got)
92		}
93		m = answerFor(t, m, "dhi.io", oneImage("nginx"), false, nil)
94		m = answerFor(t, m, "nexus-prod", oneImage("nginx"), false, nil)
95		m = answerFor(t, m, "dev", oneImage("nginx"), false, nil)
96		wantHeaderKeys(t, m, "Images")
97	}
98	
99	// C3: a registry cut at a cap is named, whether it answered or found nothing.
100	func TestAPartialRegistryIsNamed(t *testing.T) {
101		tests := []struct {
102			name   string
103			images []imagesearch.Image
104			want   []string
105			vals   map[string]string
106		}{
107			{"ok and partial", oneImage("nginx"), []string{"Images", "Partial"}, map[string]string{"Partial": "hub"}},
108			{"no result and partial", nil, []string{"Images", "Partial", "No result"}, // V4: Partial before No result
109				map[string]string{"Partial": "hub", "No result": "hub"}},
110		}
111		for _, tt := range tests {
112			t.Run(tt.name, func(t *testing.T) {
113				withImageSearcher(t, &fakeSearcher{})
114				m := registryModel(t, anonymousRegistry("docker.io", "hub"))
115				m = feed(t, m, testutil.Resize(200, 40))
