98	func TestSummarizeSearch(t *testing.T) {
99		ok := imagesearch.Outcome{Verdict: imagesearch.VerdictOK}
100		okPartial := imagesearch.Outcome{Verdict: imagesearch.VerdictOK, Partial: true}
101		none := imagesearch.Outcome{Verdict: imagesearch.VerdictNoResult}
102		nonePartial := imagesearch.Outcome{Verdict: imagesearch.VerdictNoResult, Partial: true}
103		skipped := imagesearch.Outcome{Verdict: imagesearch.VerdictNoResult, Skipped: true}
104		refused := imagesearch.Outcome{Verdict: imagesearch.VerdictRefused}
105		failed := imagesearch.Outcome{Verdict: imagesearch.VerdictFailed}
106	
107		tests := []struct {
108			name     string
109			keys     []string
110			outcomes map[string]imagesearch.Outcome
111			live     bool
112			want     searchSummary
113		}{
114			{"no keys", nil, nil, true, searchSummary{}},
115			{"ok without a mark appears nowhere", []string{"a"}, map[string]imagesearch.Outcome{"a": ok}, true, searchSummary{}},
116			{"no outcome in a live lot is pending", []string{"a", "b"}, nil, true, searchSummary{Pending: 2}},
117			{"no outcome in an abandoned lot is interrupted", []string{"a", "b"},
118				map[string]imagesearch.Outcome{"a": ok}, false, searchSummary{Interrupted: []string{"b"}}},
119			{"failed", []string{"a"}, map[string]imagesearch.Outcome{"a": failed}, true, searchSummary{Failed: []string{"a"}}},
120			{"refused", []string{"a"}, map[string]imagesearch.Outcome{"a": refused}, true, searchSummary{Refused: []string{"a"}}},
121			{"ok partial", []string{"a"}, map[string]imagesearch.Outcome{"a": okPartial}, true, searchSummary{Partial: []string{"a"}}},
122			{"no result", []string{"a"}, map[string]imagesearch.Outcome{"a": none}, true, searchSummary{NoResult: []string{"a"}}},
123			{"no result and partial is both", []string{"a"}, map[string]imagesearch.Outcome{"a": nonePartial}, true,
124				searchSummary{NoResult: []string{"a"}, Partial: []string{"a"}}},
125			{"skipped is only skipped", []string{"a"}, map[string]imagesearch.Outcome{"a": skipped}, true,
126				searchSummary{Skipped: []string{"a"}}},
127			{"names follow the keys, not the map", []string{"z", "m", "a"},
128				map[string]imagesearch.Outcome{"a": refused, "m": refused, "z": refused}, true,
129				searchSummary{Refused: []string{"z", "m", "a"}}},
130			{"a mix", []string{"hub", "prod", "dev", "slow", "third"},
131				map[string]imagesearch.Outcome{"hub": ok, "prod": refused, "dev": failed, "slow": okPartial}, true,
132				searchSummary{Pending: 1, Failed: []string{"dev"}, Refused: []string{"prod"}, Partial: []string{"slow"}}},
133		}
134		label := func(k string) string { return "L:" + k }
135		for _, tt := range tests {
136			t.Run(tt.name, func(t *testing.T) {
137				got := summarizeSearch(tt.keys, tt.outcomes, tt.live, label)
138				// Names carry the label, not the key.
139				want := tt.want
140				for _, p := range []*[]string{&want.Interrupted, &want.Failed, &want.Refused, &want.Partial, &want.NoResult, &want.Skipped} {
141					for i, k := range *p {
142						(*p)[i] = "L:" + k
143					}
144				}
145				if !reflect.DeepEqual(got, want) {
146					t.Errorf("summarizeSearch = %+v, want %+v", got, want)
147				}
148			})
149		}
150	}
